cat > people.cypher <<'EOF'
MERGE (o:Person {name: 'Oskar'}) SET o.role = 'engineer';
MERGE (m:Person {name: 'Michael'}) SET m.role = 'engineer';
MERGE (w:Person {name: 'Will'}) SET w.role = 'maintainer';
EOF

import json

import relate


def run_cypher(query, params=None, *, database="./team.rl", read_only=True, max_rows=100):
    """Run one Cypher statement and return a result an agent can parse."""
    try:
        with relate.connect(database, read_only=read_only) as conn:
            cursor = conn.execute(query, params)
            rows = cursor.fetch(max_rows)
            return {
                "columns": cursor.columns,
                "rows": [row.to_dict() for row in rows],
                "truncated": len(cursor) > max_rows,
            }
    except relate.Error as error:
        return {
            "error": {
                "type": type(error).__name__,
                "gql_status": error.gql_status,
                "retryable": bool(error.retryable),
                "message": str(error),
            }
        }


if __name__ == "__main__":
    result = run_cypher(
        "MATCH (p:Person) RETURN p.name AS person, p.role AS role ORDER BY person",
        max_rows=2,
    )
    print(json.dumps(result, indent=2, default=str))
